import{_ as e,c as r,o as p,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"18、【蛊】 巽下艮上","description":"周易尚氏学 - 18、【蛊】 巽下艮上","frontmatter":{"title":"18、【蛊】 巽下艮上","description":"周易尚氏学 - 18、【蛊】 巽下艮上"},"headers":[],"relativePath":"zh/classics/shangshi/023.md","filePath":"zh/classics/shangshi/023.md"}'),h={name:"zh/classics/shangshi/023.md"};function s(t,a,l,n,c,d){return p(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_18、【蛊】-巽下艮上" tabindex="-1">18、【蛊】 巽下艮上 <a class="header-anchor" href="#_18、【蛊】-巽下艮上" aria-label="Permalink to “18、【蛊】 巽下艮上”">​</a></h1><p>左传虫蛊。而归藏作蜀。《诗》曰：蜎蜎者蠋；蠋，葵中蚕也。诗诂蜀已有虫。再加虫俗字。然则蜀亦虫。与蛊义同也。蛊败也。坏也。卦上山震木。为材木之所出。乃下卦为巽。巽陨落故败。又巽为虫。虫蠢物朽腐。大过曰栋挠。易林旅之履云。木内生蠢。蠢即蛊。皆以巽也。故坏。礼王制。执左道以乱政疏云。蠢者损坏之名。周礼秋官庶氏。掌除毒蛊。郑注毒蛊虫物而病害人者。又翦氏。掌除蠢物。凡庶蛊之事。注蛊。蠢之类。又史记秦德公二年初伏。以狗御蛊。注蛊恶气。是蛊之为蠢为腐坏甚明。又左传云。女惑男。风落山。谓之蛊。女惑男。男败。风落山。山败。亦以败坏说蛊。荀爽谓蛊为事。朱子盖以为不安。又曰坏极而有事。夫卦名皆由卦象而生。诂蛊为事为惑。皆正训不误。而此则义为败坏。亦卦象所命也。彖曰巽而止蛊。亦以败坏为说。若必拘序卦而训为事。则此句义难通矣。阳得阴则通。坤为大川。为事。刚往坤上。下履重阴。容民得众。故曰利涉大川。曰往有事。乾元为甲、蛊之先为泰。乾为日。三爻故曰先甲三日。乃由泰反否而蛊为之始。初交上为蛊。二三随上成否。甲之在下者反上。先甲变为后甲矣。故又曰后甲三日。蛊旁通随。随者由否反泰之始。上爻下成随。四五随下成泰。甲之在上者反下。后甲又变为先甲矣。否泰相循环相终始。来往　信。天道因如是也。</p><p>彖曰。蛊刚上而柔下。巽而止蛊。蛊元亨而天下治也。利涉大川。往有事也。先甲三日。后甲三日。终则有始。天行也。</p><p>行道也。泰者随之终。蛊者否之始。故曰终则有始。</p><p>象曰。山下有风。蛊。君子以振民育德。</p><p>风止山下。气郁不通。故蛊。蛊则不生育。振而作之。所以救蛊而育德也。象义有因卦象而取法者。有反省者。兹则反省者也。</p><p>初六。于父之蛊。有子考。无咎。厉终吉。</p><p>初虽不当位。然上承重阳。与上合志。与升初六同。故吉。易林以震巽为父母。详焦氏易诂朱汉上以复姤为小父母。复殷（左艮）仍震巽。初伏震。故曰父。曰了。乾正也。能正父蛊。故曰有子考。逸周书谧法云。考成也。左氏襄十三年弥庙疏。考成也。言有成德也。有子考者。即谓有子能成就先业也。故无咎。风陨故厉。承阳故终吉。马融王肃读考字绝句。王注作考无咎。非也。</p><h3 id="象曰。乾父之蛊。意承考也。" tabindex="-1">象曰。乾父之蛊。意承考也。 <a class="header-anchor" href="#象曰。乾父之蛊。意承考也。" aria-label="Permalink to “象曰。乾父之蛊。意承考也。”">​</a></h3><p>意承考。谓初上承重阳。能承继先德也。承顺也。巽象。</p><p>九二：干母之蛊，不可贞。</p><h3 id="象曰。干母之蛊。得中道也。" tabindex="-1">象曰。干母之蛊。得中道也。 <a class="header-anchor" href="#象曰。干母之蛊。得中道也。" aria-label="Permalink to “象曰。干母之蛊。得中道也。”">​</a></h3><p>二五得中。</p><p>九三。乾父之蛊。小有悔。无大咎。</p><p>三震体。故亦因父。按九三上虽无应。然当位。前临重阴。与大畜九三象同。当吉。乃大畜九三利往。此云小悔无大咎者。以体下断也。凡巽体上交多不吉。先儒不知其故在本弱。故多误解。</p><h3 id="象曰。乾父之蛊。终无咎也。" tabindex="-1">象曰。乾父之蛊。终无咎也。 <a class="header-anchor" href="#象曰。乾父之蛊。终无咎也。" aria-label="Permalink to “象曰。乾父之蛊。终无咎也。”">​</a></h3><p>九三前临重阴。利往。故终无咎。</p><p>六四。裕父之蛊。往见吝。</p><p>裕宽也。虞云不能净父过也。前遇敌。阴遇阴则窒。故往吝。</p><h3 id="象曰。裕父之蛊。往未得也。" tabindex="-1">象曰。裕父之蛊。往未得也。 <a class="header-anchor" href="#象曰。裕父之蛊。往未得也。" aria-label="Permalink to “象曰。裕父之蛊。往未得也。”">​</a></h3><p>六五。干父之蛊。用誉。</p><p>得中。有应。上承阳。而艮为名。故可致闻誉。</p><h3 id="象曰。乾父用誉。承以德也。" tabindex="-1">象曰。乾父用誉。承以德也。 <a class="header-anchor" href="#象曰。乾父用誉。承以德也。" aria-label="Permalink to “象曰。乾父用誉。承以德也。”">​</a></h3><p>德谓阳。承以德。言上承阳也。</p><p>上九。不事王侯。高尚其事。</p><p>三震为王。为诸侯。上不应之。故曰不事王侯。言不事王侯之事也。高居物表。逍遥事外。故曰高尚其事。</p><h3 id="象曰。不事王侯。志可则也。" tabindex="-1">象曰。不事王侯。志可则也。 <a class="header-anchor" href="#象曰。不事王侯。志可则也。" aria-label="Permalink to “象曰。不事王侯。志可则也。”">​</a></h3><p>则法也。不事王侯。若共伯和吴季礼之流是也。作奉事者非。</p>',28)])])}const m=e(h,[["render",s]]);export{_ as __pageData,m as default};
